import {config,clone,difficulties,validateProgress,parseImport,missionDone,droneDone,setMission,setDifficulty,setDrone,setTrophy,setWeapon,nextMission,resourcePlan,estimateRuns,arsenalProgress} from './model.js';
import {itemName,missionGuideHtml,droneAuditHtml,equipmentDescriptionHtml,researchIssuesHtml} from './guide.js';
import {freshWeaponFilters,weaponCatalogHtml} from './weapons.js';
let weaponAdvancedOpen=false;
const weaponFilters=freshWeaponFilters(),heldWeapons=new Set(),openedWeapons=new Set();
const resetWeaponFilters=()=>{Object.assign(weaponFilters,freshWeaponFilters());heldWeapons.clear();};
import {adviceHtml,weaponAdviceHtml} from './advice.js';
const openAdviceRoutes=new Set();
const source=import.meta.url.includes('/dist/');
const {createStore}=await import(new URL(source?'../../../shared/roadmap-store.js':'../../shared/roadmap-store.js',import.meta.url));
const {setupSync}=await import(new URL(source?'../../talos2/dist/roadmap/sync.js':'../talos2/roadmap/sync.js',import.meta.url));
const read=async name=>{const result=await fetch(new URL(name,import.meta.url));if(!result.ok)throw Error('攻略資料讀取失敗：'+name);return result.json();};
const [catalog,droneCatalog,equipmentCatalog,adviceData]=await Promise.all([read('data/catalog.json'),read('data/drones.json'),read('data/equipment.json'),read('data/advice.json')]);
const {missions,trophies}=catalog,{drones}=droneCatalog,{weapons}=equipmentCatalog;
const allSources=[...catalog.sources,...droneCatalog.sources,...equipmentCatalog.sources,...adviceData.sources];
const core=window.SideProjectSync,$=id=>document.getElementById(id);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={overview:'白金進度',roadmap:'任務 Roadmap',drones:'Drone 收集中心',trophies:'獎盃中心',advice:'出擊與養成',weapons:'武器圖鑑',equipment:'裝備與挑戰',resources:'資源規劃器',sources:'來源與查證'};
const categoryNames={story:'主線',incidental:'順路',challenge:'特殊挑戰',collection:'收集',grind:'作業',online:'線上／多人',difficulty:'高難度'};
const resourceNames={credits:'Credits',red:'紅色 Energy Gems',blue:'藍色 Energy Gems',yellow:'黃色 Energy Gems'};
const filters={search:'',status:'all',range:'all',category:'all',type:'all',rank:'all'};
let progress,review,refreshPending=false,blocked=false;
const revealed=new Set();
const view=()=>Object.hasOwn(names,new URL(location.href).searchParams.get('view'))?new URL(location.href).searchParams.get('view'):'overview';
const current=()=>new URL(location.href).searchParams.get('mission')||progress?.settings.currentMission||'m01';
const droneFor=id=>drones.find(d=>d.missionId===id);
const missionName=id=>{const m=missions.find(m=>m.id===id);return m?'M'+String(m.number).padStart(2,'0')+' · '+m.officialName:'Practice';};
const option=(rows,value)=>rows.map(([key,label])=>`<option value="${escape(key)}" ${value===key?'selected':''}>${escape(label)}</option>`).join('');
const sourceLinks=ids=>`<div class="sources">${[...new Set(ids||[])].map(id=>allSources.find(s=>s.id===id)).filter(Boolean).map(s=>`<a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)}${s.readVia==='search-result'?'（僅搜尋摘要）':''} ↗</a>`).join('')}</div>`;
const check=(attr,id,checked,label)=>`<label class="check-label"><input type="checkbox" ${attr}="${escape(id)}" ${checked?'checked':''}>${label}</label>`;
const button=(v,text,mission='')=>`<button data-go="${v}" ${mission?'data-mission-link="'+escape(mission)+'"':''}>${escape(text)}</button>`;
function message(text){$('feedback').hidden=!text;$('feedback').textContent=text;}
async function action(fn){try{await fn();}catch(error){message(error.message);const status=document.querySelector('dialog[open] [id$="status"]');if(status)status.textContent=error.message;try{progress=await store.get();refresh();}catch{/* 原文保留；不可用空白進度覆蓋。 */}}}
const store=createStore(config,core,()=>{if(refreshPending)return;refreshPending=true;queueMicrotask(async()=>{refreshPending=false;try{progress=await store.get();refresh();}catch(error){blocked=true;message(error.message);}});});
const update=fn=>store.update(p=>{fn(p);return p;});
function go(next,mission){resetWeaponFilters();const url=new URL(location.href);url.searchParams.set('view',next);if(mission)url.searchParams.set('mission',mission);else url.searchParams.delete('mission');history.pushState({},'',url);Object.assign(filters,{search:'',status:'all',range:mission?String(Math.floor((Number(mission.slice(1))-1)/10)):'all',category:'all',type:'all',rank:'all'});render();window.scrollTo(0,0);if(mission&&next==='roadmap')focusMission(mission);else $('app').focus({preventScroll:true});document.querySelector('.rail').classList.remove('nav-open');$('nav-toggle').setAttribute('aria-expanded','false');}
function focusMission(id){requestAnimationFrame(()=>{const el=$('mission-'+id);if(el){el.scrollIntoView({block:'start'});el.querySelector('[data-mission]')?.focus({preventScroll:true});}});}
function counts(){return {mission:missions.filter(m=>missionDone(progress,m.id)).length,drone:drones.filter(d=>droneDone(progress,d.id)).length,trophy:trophies.filter(t=>progress.trophies[t.id]?.earned).length};}
function stats(){const c=counts();return `<div class="stats"><div><small>任務完成</small><strong id="mission-count">${c.mission} / 52</strong></div><div><small>白金獎盃</small><strong id="trophy-count">${c.trophy} / ${trophies.length}</strong></div><div><small>Drone 回收</small><strong id="drone-count">${c.drone} / 55</strong></div><div><small>目前任務</small><strong id="current-mission">${escape(progress.settings.currentMission.toUpperCase())}</strong></div></div>`;}
function recommendation(){const mission=nextMission(progress,missions),uncollected=drones.find(d=>!droneDone(progress,d.id));if(trophies.every(t=>progress.trophies[t.id]?.earned))return {title:'白金清單已全部勾選',text:'可隨時回看攻略與補登遊戲紀錄。',view:'trophies'};if(mission&&!progress.trophies.t02?.earned)return {title:missionName(mission.id),text:'推進主線，同時回收本關 Drone；成功完成任務後再勾選。',view:'roadmap',mission:mission.id};if(uncollected)return {title:'補齊 Drone Buff 收集條件',text:missionName(uncollected.missionId)+'：'+uncollected.route,view:'drones'};return {title:'清理剩餘獎盃',text:'核對高難度、線上與裝備目標；以 PSN 實際跳盃為準。',view:'trophies'};}
function overviewHtml(){const c=counts(),next=recommendation(),remaining=trophies.filter(t=>!progress.trophies[t.id]?.earned);return `<div class="summary-goals"><section class="panel next-panel"><h2>推薦下一步</h2><p class="next">${escape(next.title)}</p><p>${escape(next.text)}</p>${button(next.view,'前往這一步',next.mission)}${button('advice','出擊配裝與升級心得',progress.settings.currentMission)}<label class="goal-picker">從目前遊玩進度開始<select id="current-select">${option(missions.map(m=>[m.id,missionName(m.id)]),progress.settings.currentMission)}</select></label><p class="muted">選擇目前任務不會代填前面任務或獎盃。</p></section><section><h2>目前最重要的提醒</h2><div class="warning"><strong>Drone 要完成任務才會登錄</strong><p>拾取後退出或失敗不能當作已回收。先在任務選擇畫面確認 Drone 圖示，再勾選。</p></div><p>獎盃實際共 ${trophies.length} 個，已含白金。本站未連接 PSN；請依 PSN 勾選。</p><h2>白金剩餘目標</h2><p class="unknown">武器已補齊本體清單；道具與外觀仍是部分庫，須另核對遊戲內全清單。</p><ul class="pending-list"><li>本體獎盃：還有 ${remaining.length} 個未勾選。</li><li>任務：還有 ${52-c.mission} 關未記錄完成。</li><li>Drone：還有 ${55-c.drone} 架未勾選。</li><li>本體武器：${arsenalProgress(progress,weapons).owned} / ${arsenalProgress(progress,weapons).total} 款已勾選持有；DLC／特典不計入。</li></ul>${button('trophies','查看剩餘獎盃')}</section></div><section><h2>任務直達</h2>${missionIndex()}</section>`;}
function missionIndex(){return `<nav class="mission-index" aria-label="52 關任務直達">${missions.map(m=>`<a href="?view=roadmap&amp;mission=${m.id}" data-go="roadmap" data-mission-link="${m.id}" class="${missionDone(progress,m.id)?'done':''}" ${current()===m.id?'aria-current="step"':''} aria-label="${escape(missionName(m.id))}">${String(m.number).padStart(2,'0')}</a>`).join('')}</nav>`;}
function filterHtml({range=false,category=false,type=false}={}){return `<div class="toolbar"><label class="search">搜尋<input id="search" type="search" value="${escape(filters.search)}" placeholder="任務、名稱、地標…" data-filter="search"></label><label>顯示<select data-filter="status" id="status-filter">${option([['all','全部'],['pending','未勾選'],['completed','已勾選']],filters.status)}</select></label>${range?`<label>任務區段<select data-filter="range" id="range-filter">${option([['all','全部 52 關'],...Array.from({length:6},(_,i)=>[String(i),'M'+String(i*10+1).padStart(2,'0')+'–M'+Math.min(52,i*10+10)])],filters.range)}</select></label>`:''}${category?`<label>分類<select data-filter="category" id="category-filter">${option([['all','全部'],...Object.entries(categoryNames)],filters.category)}</select></label>`:''}${type?`<label>武器類型<select data-filter="type" id="type-filter">${option([['all','全部'],...[...new Set(weapons.map(w=>w.type))].map(v=>[v,v])],filters.type)}</select></label><label>等級<select data-filter="rank" id="rank-filter">${option([['all','全部'],...[...new Set(weapons.map(w=>w.rank).filter(Boolean))].map(v=>[v,v])],filters.rank)}</select></label>`:''}</div>`;}
const matches=text=>!filters.search||String(text).toLocaleLowerCase().includes(filters.search.toLocaleLowerCase());
function stateMatch(done){return filters.status==='all'||filters.status==='pending'&&!done||filters.status==='completed'&&done;}
function missionTrophies(m){return trophies.filter(t=>t.missionIds.includes(m.id)||m.trophyIds.includes(t.id));}
function missionWeapons(m){return weapons.filter(w=>(w.missionIds||[]).includes(m.id));}
function roadmapHtml(){const rows=missions.filter(m=>matches([missionName(m.id),...m.enemies,...m.bosses,...m.tactics,m.unlockRewards.map(itemName).join(' '),droneFor(m.id)?.landmark,droneFor(m.id)?.route].join(' '))&&stateMatch(missionDone(progress,m.id),!progress.missions[m.id])&&(filters.range==='all'||String(Math.floor((m.number-1)/10))===filters.range));return `${missionIndex()}<div class="toolbar"><label class="search">快速跳轉任務<select id="mission-jump">${option(missions.map(m=>[m.id,missionName(m.id)]),current())}</select></label><button id="resume">前往下一個未完成任務</button></div>${filterHtml({range:true})}<p class="muted">52 關均可直接開始。完成關卡預設收合，警示仍保留；取消完成會一併清除該關已確認難度，Drone 與獎盃保持獨立。</p><div id="results">${rows.length?rows.map(missionHtml).join(''):'<p class="empty">沒有符合條件的任務。試著清除篩選。</p>'}</div>`;}
function missionHtml(m){
 const done=missionDone(progress,m.id),compact=done&&!revealed.has(m.id)&&!filters.search,related=missionTrophies(m),ws=missionWeapons(m),drone=droneFor(m.id);
 return `<article class="row mission-row ${done?'done':''}" id="mission-${m.id}" data-mission-row="${m.id}"><div class="mission-head">${check('data-mission',m.id,done,'已完成')}<h2>${escape(missionName(m.id))}</h2><button data-peek="${m.id}" aria-expanded="${!compact}">${compact?'展開攻略':'收合攻略'}</button></div><p class="mission-status">${escape(m.stage)} · ${done?'✓ 任務完成':'□ 任務'} · Drone ${droneDone(progress,drone.id)?'✓':'□'}</p><p class="persistent-warning">${escape([...(m.warnings||[]),'Drone 拾取後須成功完成任務。',drone.warning].filter(Boolean).join(' '))}</p><div class="mission-body" ${compact?'hidden':''}><div class="difficulty-list" aria-label="${m.id} 難度完成紀錄">${difficulties.map(key=>`<label><input type="checkbox" data-difficulty="${m.id}" data-key="${key}" ${progress.missions[m.id]?.difficulties[key]?'checked':''}>${key}</label>`).join('')}</div><p class="mission-prep-link">${button('advice','出擊前：裝備需求與升級路線',m.id)}</p><div class="guide-grid"><section>${missionGuideHtml(m,{escape,sourceLinks})}<h3>相關獎盃</h3>${related.length?related.map(t=>trophyMini(t)).join(''):'<p class="unknown">來源未指定本關專屬獎盃；其他條件可到獎盃中心查看。</p>'}<h3>已收錄的相關武器</h3>${ws.length?ws.map(w=>`<p><a href="?view=weapons#weapon-${escape(w.id)}" data-weapon-link="${escape(w.id)}">${escape(itemName(w))}</a> · ${w.contentGroup==='dlc'?'DLC · ':''}${escape(w.unlockCondition)}</p>`).join(''):'<p class="unknown">來源尚未建立本關武器關聯；請核對上方表列獎勵與圖鑑解鎖條件。</p>'}</section>${droneHtml(drone,false)}</div><div class="actions"><button data-set-current="${m.id}">設為目前任務</button>${m.number<52?button('roadmap','下一關 →',missions[m.number].id):button('overview','返回總覽')}</div></div></article>`;
}
function routeMap(d){return `<svg class="route-map" viewBox="0 0 420 160" role="img" aria-label="${escape(d.landmark)} 路線流程示意（非地形圖）"><title>起點 → 方向 → 地標；不按比例，非實測地圖</title><path class="route-line" d="M35 50H385"/><circle cx="35" cy="50" r="11"/><circle cx="210" cy="50" r="11"/><circle cx="385" cy="50" r="11"/><text x="35" y="88" text-anchor="middle">起點</text><text x="210" y="112" text-anchor="middle">${escape(d.direction.slice(0,16))}</text><text x="405" y="142" text-anchor="end">${escape(d.landmark.slice(0,28))}</text></svg><p class="route-note">原創路線流程示意，非地形／實測座標；請搭配文字與來源定位。</p>`;}
function droneHtml(d,link=true){
 const done=droneDone(progress,d.id);
 return `<section class="drone-guide" id="${escape(d.id)}"><h3>${d.missionId?d.missionId.toUpperCase():'Practice '+d.practiceNumber} · M.I.A. Drone</h3><div class="drone-state">${check('data-drone',d.id,done,d.missionId?'完成任務並回收 Drone':'回收 Drone')}</div>${d.warning?`<p class="warning">${d.verification==='conflict'?'來源衝突（待查）':'核對結果'}：${escape(d.warning)}</p>`:''}<details class="drone-location" data-confirmed="${done}" ${done?'':'open'}><summary>${done?'查看已完成的回收路線':'回收路線與地標'}</summary><div class="drone-route-body"><div><p><strong>${escape(d.route)}</strong></p><p>起點方向：${escape(d.direction)}<br>定位地標：${escape(d.landmark)}<br>推薦 PA-Gear：${escape(d.recommendedGear)}（編輯建議）<br>障礙物：${d.obstacle?escape(d.obstacle.action)+(d.obstacle.required?'（需要）':'（可選）'):'來源未確認需破壞障礙物'}</p><p class="unknown">${d.verification==='conflict'?'來源描述仍有差異，保留候選；待影像或實機核對。':d.verification==='source-reconciled'?'依地標收斂文字來源；剩餘限制見核對結果，尚未實機走查。':'已核對文字來源；尚未實機走查。'}</p>${sourceLinks(d.sourceIds)}${droneAuditHtml(d,{escape,sourceLinks})}</div><div>${routeMap(d)}</div></div></details>${link&&d.missionId?button('roadmap','開啟對應任務',d.missionId):''}</section>`;
}
function dronesHtml(){const rows=drones.filter(d=>stateMatch(droneDone(progress,d.id),progress.drones[d.id]?.status==='unknown')&&matches([d.missionId,d.practiceNumber?'Practice 練習場':'',missionName(d.missionId),d.route,d.landmark].join(' ')));return `<p class="warning">戰役 Drone 拾取後要成功完成該任務才計入。55 架條件齊全也不會自動勾選 Drone Buff。</p>${filterHtml()}<div id="results"><section class="collection-group"><h2>主線任務 · 52 架</h2>${rows.filter(d=>d.missionId).map(d=>droneHtml(d)).join('')||'<p class="empty">沒有符合條件的任務 Drone。</p>'}</section><section class="collection-group"><h2>Practice · 3 架</h2>${rows.filter(d=>!d.missionId).map(d=>droneHtml(d)).join('')||'<p class="empty">沒有符合條件的 Practice Drone。</p>'}</section></div>`;}
function trophyMini(t){return `<div>${check('data-trophy',t.id,progress.trophies[t.id]?.earned,escape(t.officialName)+' · PSN 已取得')}</div>`;}
function trophyCondition(t){
 if(t.officialName==='Drone Buff'){const count=counts().drone;return `條件追蹤（推導）：${count} / 55 架已勾選回收。${count===55?'請另外核對 PSN；尚未替你標為取得。':'條件尚未齊全。'}`;}
 if(t.officialName==='Complete Arsenal'){const a=arsenalProgress(progress,weapons);return `本體持有：${a.owned} / ${a.total} 款。DLC／特典不計入；勾滿條件也不會自動替你勾選 PSN 獎盃。`;}
 return '條件尚未由網站完整追蹤；請以遊戲紀錄與 PSN 核對。';
}
function trophiesHtml(){const rows=trophies.filter(t=>stateMatch(progress.trophies[t.id]?.earned===true,!progress.trophies[t.id])&&matches([t.officialName,t.officialDescription,...t.howTo].join(' '))&&(filters.category==='all'||t.category===filters.category));return `<p>PS4 本體 ${trophies.length} 個，已含白金；DLC 不計入。已取得與條件推導各自獨立。</p>${filterHtml({category:true})}<div id="results">${rows.map(t=>{const earned=progress.trophies[t.id]?.earned;return `<article class="row trophy-row" id="trophy-${t.id}"><div class="row-heading">${check('data-trophy',t.id,earned,`<h2>${escape(t.officialName)}</h2>`)}<span class="pill">${escape(categoryNames[t.category]||t.category)} · ${escape(t.grade)}</span></div><p class="official">${escape(t.officialDescription)}</p><p class="metadata">可錯過：${t.missable===null?'待查證':t.missable?'是':'否'} · 線上必要：${t.onlineRequired===null?'待查證':t.onlineRequired?'是':'否'} · 多人必要：${t.multiplayerRequired===null?'待查證':t.multiplayerRequired?'是':'否'}</p><p>${escape(trophyCondition(t))}</p><details ${earned?'':'open'}><summary>操作與注意事項</summary><p>推薦時機：${escape(t.timing)}</p><ol>${t.howTo.map(text=>`<li>${escape(text)}</li>`).join('')}</ol>${t.notes.map(text=>`<p class="warning">${escape(text)}</p>`).join('')}<div class="actions">${t.missionIds.map(id=>button('roadmap',id.toUpperCase(),id)).join('')}</div>${t.weaponTypes.length?`<p>相關武器類型：${escape(t.weaponTypes.join('、'))}</p>`:''}<p class="unknown">額外成本：${t.extraCost?escape(JSON.stringify(t.extraCost)):'無可靠逐盃估算，不顯示猜測值'} · 查證：${escape(t.verification)}</p>${sourceLinks(t.sourceIds)}</details></article>`;}).join('')||'<p class="empty">沒有符合條件的獎盃。</p>'}</div>`;}
function weaponsHtml(){return weaponCatalogHtml({adviceNotes:adviceData.weaponNotes,weaponAdviceHtml,weapons,progress,filters:weaponFilters,held:heldWeapons,opened:openedWeapons,missions,trophies,droneCount:counts().drone,advancedOpen:weaponAdvancedOpen||matchMedia('(min-width:1201px)').matches,escape,option,sourceLinks,button});}
function equipmentHtml(){return `<p>道具、外觀、PA-Gear、傭兵與高難度資料使用可擴充結構。以下只列本次有來源的條目；仍是部分庫。</p>${['paGear','items','cosmetics','mercenary','challenges'].map((key,i)=>`<section><h2>${['PA-Gear','道具','外觀','傭兵模式','高難度挑戰'][i]}</h2>${(equipmentCatalog[key]||[]).map(item=>`<article class="row"><h3>${escape(itemName(item))}</h3>${equipmentDescriptionHtml(item,{escape,sourceLinks})}${item.id?check('data-equipment',item.id,progress.equipment[item.id]?.obtained,'取得／完成'):''}</article>`).join('')||'<p class="unknown">本類逐項資料尚未查證，未以猜測內容填滿。</p>'}</section>`).join('')}`;}
const currencyInputs=(prefix,values)=>Object.entries(resourceNames).map(([key,name])=>`<label>${name}<input type="number" min="0" step="1" id="${prefix}-${key}" ${prefix==='balance'?'data-resource="'+key+'"':''} value="${values[key]??0}" required></label>`).join('');
function resourcesHtml(){const plan=resourcePlan(progress,weapons),entries=Object.entries(progress.farmRuns);return `<p class="resource-advice">不知道刷哪裡？${button('advice','查看分階段刷取心得')}</p><section><h2>目前資源</h2><div class="counter-grid">${currencyInputs('balance',progress.resources)}</div><div class="resource-result">${Object.entries(resourceNames).map(([key,name])=>`<p><span>${name}</span><span>目標 ${plan.total[key].toLocaleString()} · 缺口 <strong>${plan.missing[key].toLocaleString()}</strong></span></p>`).join('')}</div><p>已列入 ${plan.targets.length} 款尚未購買的目標。${plan.unknown.length?`${plan.unknown.length} 款價格未查證，尚未包含於數值；此缺口不是完整預算。`:''}</p>${button('weapons','選擇目標裝備')}</section><section class="panel"><h2>手動記錄實測刷取</h2><p>填入這一批的總場次、總時間與總收益。估算只使用你的紀錄，不採用未驗證的固定效率。</p><form id="farm-form"><div class="form-grid"><label>任務<select name="missionId">${option(missions.map(m=>[m.id,missionName(m.id)]),progress.settings.currentMission)}</select></label><label>難度<select name="difficulty">${option(difficulties.map(d=>[d,d]),'Easy')}</select></label><label>總場次<input name="runs" type="number" min="1" step="1" value="1" required></label><label>總時間（分鐘）<input name="minutes" type="number" min="0.01" step="0.01" value="5" required></label></div><h3>這一批總收益</h3><div class="counter-grid">${currencyInputs('yield',{})}</div><button class="primary spacer" type="submit">保存實測</button></form></section><section><h2>自己的實測紀錄</h2>${entries.map(([id,row])=>{const n=estimateRuns(row,plan.missing);return `<article class="row"><h3>${escape(missionName(row.missionId))} · ${escape(row.difficulty)}</h3><p>${row.runs} 場 / ${row.minutes} 分鐘 · ${Object.entries(resourceNames).map(([key,name])=>name+' '+row.yield[key]).join(' / ')}</p><p>${n===null?'此紀錄缺少所需資源的產出，無法單靠此關填滿缺口。':`以這筆平均估算再 ${n} 場、約 ${(n*row.minutes/row.runs).toFixed(1)} 分鐘；樣本 ${row.runs} 場，實際收益可能變動。`}</p><button data-delete-farm="${escape(id)}">刪除此筆實測</button></article>`;}).join('')||'<p class="empty">尚無自己的實測紀錄。</p>'}</section>`;}
function sourcesHtml(){return `<section><h2>資料範圍與可靠性</h2><p>查證日期 ${escape(catalog.checkedAt)}。52 個任務、55 架 Drone、PS4 本體 ${trophies.length} 盃（含白金）。沒有將 Steam 名稱或 DLC 混進 PSN 計算。</p><p class="warning">原需求「45 盃」與公開 PS4 清單不同，已採實際 44 盃。官方逐盃數字 ID 尚未核對，t00–t43 為本站穩定 ID。</p><p>文字來源核對不等於實機驗收。52 關已補來源可支持的敵人、Boss、大型威脅、獎勵與具體步驟；適用難度、無法擊破的威脅及仍待查證的欄位各自標示。未查到英文名稱者保留日文原名，不臆造英譯。本站以白金攻略為主要導航。</p><p>Drone 已複核 7 筆差異：6 筆依共同地標收斂；M32 原始高度仍有衝突，保留頂端／底座候選，不宣稱已解決。所有地點尚未實機重走。</p><p>路線圖由本頁自行繪製，只表示起點、方向與地標的閱讀順序；沒有複製攻略圖片，也不提供未驗證的座標。Drone 有歧異的項目直接保留警示。</p><p>武器已列出 312 款本體、40 款 Golden Storm 與 8 款特典。道具／外觀庫仍未齊全，不能因此宣稱白金清理清單已完整。未提供個人真實 13 盃初始狀態，所有玩家皆從空白紀錄開始。</p><h2>武器清單逐類核對</h2><p>本體 312 款按 Wiki 總覽與 GameFAQs 獨立清單逐類比對；另列 DLC 40、特典 8。名稱清單完整，不表示每個英文名稱、成本、配裝與實機效果都已驗證。</p><div class="weapon-audit-table"><table><thead><tr><th>類型</th><th>本體</th><th>DLC</th><th>特典</th></tr></thead><tbody>${equipmentCatalog.weaponAudit.typeCounts.map(row=>`<tr><th>${escape(row.type)}</th><td>${row.base}</td><td>${row.dlc}</td><td>${row.bonus}</td></tr>`).join('')}</tbody></table></div><p>${weapons.filter(w=>Object.values(w.price).some(v=>v===null)).length} 款的成本仍有未知欄位；${weapons.filter(w=>!w.officialName).length} 款保留日文原名、英文待核。SQ-マウナケアDA 與 ER-ソーネード 在成本表漏列，已從性能表與任務獎勵補入，沒有虛構價格。Aisha A2／A3 等名稱差異保留別名與說明。</p>${sourceLinks(['full-weapon-index','equip-faq-names'])}<h2>來源</h2>${allSources.map(s=>`<p class="source-row"><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)}</a></p>`).join('')}<h2>進度與同步</h2><p>人工完成紀錄、條件推導與未知分開。IndexedDB、快照、匯入原文、同步 Base / pending 均限定 game-companion.edfir.；不使用 Service Worker，不讀寫其他遊戲進度。手動 Drive 共用原授權與條件寫入安全閘門。真實 Google 與 PS4 跳盃尚待使用者驗收。</p></section>`;}
const pages={advice:()=>adviceHtml({data:adviceData,mission:missions.find(m=>m.id===current())||missions[0],missions,weapons,progress,escape,option,button,sourceLinks}),overview:overviewHtml,roadmap:roadmapHtml,drones:dronesHtml,trophies:trophiesHtml,weapons:weaponsHtml,equipment:equipmentHtml,resources:resourcesHtml,sources:sourcesHtml};
function relatedLinks(){
 const link=(kind,id,label)=>{const a=document.createElement('a');a.href='?view='+kind+'#'+(kind==='weapons'?'weapon-':'trophy-')+id;a.dataset[kind==='weapons'?'weaponLink':'trophyLink']=id;a.textContent=label;return a;};
 if(['sources','equipment'].includes(view()))$('app').insertAdjacentHTML('beforeend',researchIssuesHtml(equipmentCatalog.issues,{escape}));
 if(view()==='roadmap'){const note=document.createElement('p');note.className='unknown';note.textContent='難度紀錄不區分線上／離線，不用來推定線上獎盃；區段為本站導航分組，並非官方章節。';$('results').before(note);}
 if(view()==='trophies')for(const t of trophies){const row=$('trophy-'+t.id);if(!row)continue;const wrap=document.createElement('div');wrap.className='sources';if(t.officialName==='Complete Arsenal'){const b=document.createElement('button');b.dataset.arsenalPending='true';b.textContent='開啟本體未持有清單';wrap.append(b);}else for(const id of t.weaponIds)wrap.append(link('weapons',id,itemName(weapons.find(w=>w.id===id))));row.querySelector('details').append(wrap);}
}
function render(){if(!progress||blocked)return;document.body.dataset.view=view();document.querySelectorAll('[data-view]').forEach(a=>{if(a.dataset.view===view())a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('app').innerHTML=`<div class="page-heading"><div><h1>${names[view()]}</h1><p class="scope">EARTH DEFENSE FORCE: IRON RAIN · PS4 本體</p></div><small id="save-state">已自動保存</small></div>${['weapons','advice'].includes(view())?'':stats()}${pages[view()]()}`;relatedLinks();document.querySelectorAll('.advice-route,.advice-farm,.prep-evidence').forEach(el=>{if(openAdviceRoutes.has(el.id))el.open=true;});}
function refresh(){
 // 操作同一頁時保留節點、焦點與捲動，避免長 Roadmap 勾選後跳頁。
 if(view()==='roadmap'&&$('results')&&filters.status==='all'){
  const c=counts();$('mission-count').textContent=c.mission+' / 52';$('drone-count').textContent=c.drone+' / 55';$('trophy-count').textContent=c.trophy+' / '+trophies.length;$('current-mission').textContent=progress.settings.currentMission.toUpperCase();
  document.querySelectorAll('[data-mission-row]').forEach(row=>{const id=row.dataset.missionRow,done=missionDone(progress,id),compact=done&&!revealed.has(id)&&!filters.search;if(!done)revealed.delete(id);row.classList.toggle('done',done);row.querySelector('[data-mission]').checked=done;row.querySelector('.mission-body').hidden=compact;const peek=row.querySelector('[data-peek]');peek.textContent=compact?'展開攻略':'收合攻略';peek.setAttribute('aria-expanded',String(!compact));const m=missions.find(m=>m.id===id);row.querySelector('.mission-status').textContent=m.stage+' · '+(done?'✓ 任務完成':'□ 任務')+' · Drone '+(droneDone(progress,droneFor(id).id)?'✓':'□');});
  document.querySelectorAll('[data-drone]').forEach(el=>{const done=droneDone(progress,el.dataset.drone);el.checked=done;const details=el.closest('.drone-guide').querySelector('.drone-location');if(details.dataset.confirmed!==String(done)){details.open=!done;details.dataset.confirmed=String(done);details.querySelector('summary').textContent=done?'查看已完成的回收路線':'回收路線與地標';}});
  document.querySelectorAll('[data-trophy]').forEach(el=>el.checked=progress.trophies[el.dataset.trophy]?.earned===true);document.querySelectorAll('[data-difficulty]').forEach(el=>el.checked=progress.missions[el.dataset.difficulty]?.difficulties[el.dataset.key]===true);document.querySelectorAll('.mission-index [data-mission-link]').forEach(el=>el.classList.toggle('done',missionDone(progress,el.dataset.missionLink)));const active=document.activeElement;if(active?.closest('.mission-body[hidden]'))active.closest('.mission-row').querySelector('[data-mission]').focus({preventScroll:true});return;
 }
 const focused=document.activeElement,focusId=focused?.id,key=focused?.dataset.drone||focused?.dataset.trophy||focused?.dataset.weapon||focused?.dataset.resource;
 const weaponKey=focused?.dataset.key,anchor=focused?.closest('.weapon-row'),anchorId=anchor?.id,anchorTop=anchor?.getBoundingClientRect().top,top=window.scrollY;render();let target=focusId?$(focusId):null;if(!target&&key)target=[...document.querySelectorAll('input,select')].find(el=>Object.values(el.dataset).includes(key)&&(!weaponKey||el.dataset.key===weaponKey));target?.focus({preventScroll:true});window.scrollTo(0,anchorId&&$(anchorId)?top+$(anchorId).getBoundingClientRect().top-anchorTop:top);
}
document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;
 if(el.dataset.close)$(el.dataset.close).close();
 if(el.dataset.go){event.preventDefault();go(el.dataset.go,el.dataset.missionLink);}
 if(el.dataset.weaponLink){event.preventDefault();openedWeapons.add(el.dataset.weaponLink);go('weapons');requestAnimationFrame(()=>{const row=$('weapon-'+el.dataset.weaponLink);row?.scrollIntoView({block:'start'});row?.querySelector('[data-weapon-peek]')?.focus({preventScroll:true});});}
 if(el.hasAttribute('data-weapon-reset')){resetWeaponFilters();render();$('weapon-search').focus();}
 if(el.dataset.arsenalPending){go('weapons');weaponFilters.scope='base';weaponFilters.unpurchased=true;render();$('weapon-search').focus({preventScroll:true});}
 if(el.dataset.weaponScope){heldWeapons.clear();weaponFilters.scope=el.dataset.weaponScope;render();document.querySelector('[data-weapon-scope="'+el.dataset.weaponScope+'"]')?.focus();}
 if(el.dataset.weaponType){heldWeapons.clear();weaponFilters.type=el.dataset.weaponType;render();document.querySelector('[data-weapon-type="'+CSS.escape(el.dataset.weaponType)+'"]')?.focus();}
 if(el.dataset.weaponPeek){const id=el.dataset.weaponPeek;openedWeapons.has(id)?openedWeapons.delete(id):openedWeapons.add(id);el.setAttribute('aria-expanded',String(openedWeapons.has(id)));el.innerHTML=(openedWeapons.has(id)?'收合 <span aria-hidden="true">−</span>':'詳情 <span aria-hidden="true">+</span>');$('detail-'+id).hidden=!openedWeapons.has(id);}
 if(el.dataset.trophyLink){event.preventDefault();go('trophies');requestAnimationFrame(()=>$('trophy-'+el.dataset.trophyLink)?.scrollIntoView());}
 if(el.dataset.peek){const id=el.dataset.peek;if(revealed.has(id))revealed.delete(id);else revealed.add(id);if(!missionDone(progress,id)){const body=el.closest('.mission-row').querySelector('.mission-body');body.hidden=!body.hidden;el.setAttribute('aria-expanded',String(!body.hidden));el.textContent=body.hidden?'展開攻略':'收合攻略';}else refresh();}
 if(el.dataset.planWeapons)void action(async()=>{const ids=el.dataset.planWeapons.split(',');await update(p=>{for(const id of ids){if(!weapons.some(w=>w.id===id)||p.weapons[id]?.purchased)continue;p.weapons[id]={unlocked:false,purchased:false,...p.weapons[id],target:true};}});go('resources');message('已加入未持有項目；請按實際需求保留目標。');});
 if(el.dataset.useFarm){const farm=adviceData.farms.find(row=>row.id===el.dataset.useFarm);if(farm){go('resources');const form=$('farm-form');form.elements.missionId.value=farm.missionId;form.elements.difficulty.value=farm.difficulty;form.scrollIntoView({block:'start'});form.elements.runs.focus({preventScroll:true});}}
 if(el.dataset.setCurrent)void action(async()=>{await update(p=>p.settings.currentMission=el.dataset.setCurrent);message('已設為目前任務；未更動其他完成紀錄。');});
 if(el.id==='resume'){const next=nextMission(progress,missions);if(next)go('roadmap',next.id);else message('所有任務都已記錄完成。');}
 if(el.dataset.deleteFarm)void action(()=>update(p=>{delete p.farmRuns[el.dataset.deleteFarm];}));
});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.filter||el.dataset.weaponFilter)return;void action(async()=>{
 if(el.dataset.mission)await update(p=>setMission(p,el.dataset.mission,el.checked));
 if(el.dataset.difficulty)await update(p=>setDifficulty(p,el.dataset.difficulty,el.dataset.key,el.checked));
 if(el.dataset.drone)await update(p=>setDrone(p,el.dataset.drone,el.checked?'confirmed':'missing'));
 if(el.dataset.trophy)await update(p=>setTrophy(p,el.dataset.trophy,el.checked));
 if(el.dataset.weapon){heldWeapons.add(el.dataset.weapon);await update(p=>{if(el.dataset.key==='target')p.weapons[el.dataset.weapon]={unlocked:false,purchased:false,...p.weapons[el.dataset.weapon],target:el.checked};else setWeapon(p,el.dataset.weapon,el.dataset.key,el.checked);});}
 if(el.dataset.equipment)await update(p=>p.equipment[el.dataset.equipment]={...p.equipment[el.dataset.equipment],obtained:el.checked,source:'manual'});
 if(el.dataset.resource){if(!el.validity.valid||!Number.isSafeInteger(Number(el.value)))throw Error('資源請填入非負整數。');await update(p=>p.resources[el.dataset.resource]=Number(el.value));}
 if(el.id==='current-select')await update(p=>p.settings.currentMission=el.value);
 if(el.id==='advice-mission')go('advice',el.value);
 if(el.id==='mission-jump')go('roadmap',el.value);
 });});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.filter==='search'){const at=el.selectionStart;filters.search=el.value;render();$('search').focus();$('search').setSelectionRange(at,at);}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.filter&&el.dataset.filter!=='search'){filters[el.dataset.filter]=el.value;render();document.querySelector('[data-filter="'+el.dataset.filter+'"]')?.focus();}});
document.addEventListener('toggle',event=>{const el=event.target;if(!el.matches('.advice-route,.advice-farm,.prep-evidence')||!el.id||!el.isConnected)return;el.open?openAdviceRoutes.add(el.id):openAdviceRoutes.delete(el.id);},true);
document.addEventListener('click',event=>{const summary=event.target.closest('#weapon-advanced>summary');if(!summary)return;event.preventDefault();weaponAdvancedOpen=!summary.parentElement.open;summary.parentElement.open=weaponAdvancedOpen;});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.weaponFilter!=='search')return;const at=el.selectionStart;weaponFilters.search=el.value;heldWeapons.clear();render();$('weapon-search').focus();$('weapon-search').setSelectionRange(at,at);});
document.addEventListener('change',event=>{const el=event.target,key=el.dataset.weaponFilter;if(!key||key==='search')return;weaponFilters[key]=el.type==='checkbox'?el.checked:el.value;heldWeapons.clear();render();$('weapon-filter-'+key)?.focus();});
document.addEventListener('submit',event=>{if(event.target.id!=='farm-form')return;event.preventDefault();const form=event.target;void action(async()=>{const data=new FormData(form),row={missionId:data.get('missionId'),difficulty:data.get('difficulty'),runs:Number(data.get('runs')),minutes:Number(data.get('minutes')),yield:Object.fromEntries(Object.keys(resourceNames).map(key=>[key,Number($('yield-'+key).value)])),source:'manual',updatedAt:Date.now()};await update(p=>p.farmRuns[crypto.randomUUID()]=row);message('已保存這批實測。');});});
$('nav-toggle').onclick=()=>{const open=$('nav-toggle').getAttribute('aria-expanded')!=='true';$('nav-toggle').setAttribute('aria-expanded',String(open));document.querySelector('.rail').classList.toggle('nav-open',open);};
window.addEventListener('popstate',()=>{resetWeaponFilters();Object.assign(filters,{search:'',status:'all',range:'all',category:'all',type:'all',rank:'all'});render();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.querySelector('.rail.nav-open')){document.querySelector('.rail').classList.remove('nav-open');$('nav-toggle').setAttribute('aria-expanded','false');$('nav-toggle').focus();}});
function download(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);try{const a=document.createElement('a');a.href=url;a.download='edfir-'+name+'.json';a.click();}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}
$('open-backup').onclick=()=>$('backup-dialog').showModal();
$('export').onclick=()=>void action(async()=>{download(await store.exportAll(),'backup');$('backup-status').textContent='已送出完整備份下載；請確認檔案已保存。';});
function importControls(){const ready=review?.downloaded&&!review?.stale;$('import-ack').disabled=!ready;$('import-apply').disabled=!ready||!$('import-ack').checked||review.choices.some(c=>!c);}
function renderDiffs(){const rows=$('import-rows');rows.replaceChildren();review.plan.conflicts.forEach((conflict,index)=>{const row=document.createElement('div');row.className='diff';const title=document.createElement('strong');title.textContent=conflict.path.join(' / ');row.append(title);const values=document.createElement('div');values.className='diff-values';for(const key of ['local','remote']){const pre=document.createElement('pre');pre.textContent=(key==='local'?'本機':'匯入')+'\n'+JSON.stringify(conflict[key],null,2);values.append(pre);}row.append(values);const select=document.createElement('select');select.setAttribute('aria-label','匯入差異 '+(index+1));for(const [v,label]of [['','請選擇'],['local','保留本機'],['remote','使用匯入']])select.add(new Option(label,v));select.value=review.choices[index];select.onchange=()=>{review.choices[index]=select.value;importControls();};row.append(select);rows.append(row);});}
$('import-file').onchange=()=>void action(async()=>{
 const file=$('import-file').files[0];$('import-file').value='';if(!file)return;if(file.size>5*1024*1024)throw Error('匯入檔超過 5 MiB，已停止。');
 review=null;const sourceRaw=await file.text(),localRaw=JSON.stringify(await store.raw());
 // 無論 JSON 能否解析，都先保存兩端；quota 失敗不進入預覽。
 await store.archive({kind:'import-raw',at:Date.now(),sourceRaw,localRaw});
 const incoming=parseImport(JSON.parse(sourceRaw),$('recovery-side').value),local=validateProgress(JSON.parse(localRaw));
 const full=core.merge(null,local,incoming,{hasBase:false});
 const defaults=full.conflicts.map(c=>c.local===undefined?'remote':'local'),merged=core.resolve(full,defaults);
 const conflicts=full.conflicts.filter(c=>c.local!==undefined&&c.remote!==undefined);
 review={sourceRaw,localRaw,stamp:localRaw,plan:{...full,data:merged,conflicts},choices:conflicts.map(()=>''),downloaded:false,stale:false};
 $('import-summary').textContent=`${conflicts.length} 筆兩端差異需選擇；單端未知欄位與項目自動保留。schema0 若存在會保留原文後轉換成 schema1。`;
 $('import-ack').checked=false;$('import-status').textContent='請比較差異、下載兩端備份並確認保存。';renderDiffs();importControls();$('backup-dialog').close();$('import-dialog').showModal();
});
for(const [id,choice]of [['import-local','local'],['import-source','remote']])$(id).onclick=()=>{if(!review)return;review.choices.fill(choice);renderDiffs();importControls();};
$('import-download').onclick=()=>void action(async()=>{if(!review)return;review.downloaded=false;$('import-ack').checked=false;importControls();try{download({gameId:'edfir',recoveryBundle:{sourceRaw:review.sourceRaw,localRaw:review.localRaw},at:Date.now()},'before-import');review.downloaded=true;$('import-status').textContent='已送出兩端備份下載；請確認保存。';}catch(error){$('import-status').textContent='備份失敗：'+error.message;}importControls();});
$('import-ack').onchange=importControls;
$('import-apply').onclick=()=>void action(async()=>{if(!review||!review.downloaded||!$('import-ack').checked||review.stale)return;try{await store.update(()=>validateProgress(core.resolve(review.plan,review.choices)),review.stamp);$('import-dialog').close();review=null;message('已套用選擇，兩端原文仍保留於完整備份。');}catch(error){review.stale=true;$('import-status').textContent=error.message;importControls();}});
try{progress=await store.open();render();const sync=setupSync(config,store,core,()=>void action(async()=>{progress=await store.get();refresh();}));$('open-sync').onclick=()=>sync.open();}catch(error){blocked=true;$('app').innerHTML='<h1>進度無法讀取</h1><p>'+escape(error.message)+'</p><p>原始資料未被覆寫。請由「備份與還原」下載完整原文。</p>';$('open-sync').disabled=true;}
